package io.github.rebrowser.data;

import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.browser.*;
import io.github.rebrowser.bootstrap.ComponentGate;
import java.nio.file.*;
import java.util.*;

/** Real HOST encrypted record/CAS lifecycle with synthetic source/key/path. No Android/Gecko. */
public final class HistoryStoreStateTest {
 static String id(String prefix,int n){return prefix+String.format(Locale.ROOT,"%032x",n);}
 static HistoryStore.Page page(int n){return new HistoryStore.Page(new HistoryStore.Source(id("ws_",1),"来源",BrowserModels.Level.TEMPORARY,true),id("tab_",n),"标题"+n,"https://example.test/"+n);}
 static void seed(BrowserMetadataStoreTest.F f)throws Exception{try(OwnedDataCatalog.View<HistoryStore.Snapshot> v=f.history.read(f.permit)){f.history.compareAndWrite(v,new HistoryStore.Snapshot(0,false,Collections.emptyList()),f.permit);}}
 @Test public void actualPauseSuppressesNewRecordsButNotReadTimeExpiry()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.recordVisit(page(1),1,f.permit);f.history.setPaused(true);assertEquals(1,f.history.recordVisit(page(2),2,f.permit).entries().size());assertEquals(0,f.history.readCurrent(1+HistoryStore.RETENTION_MS,f.permit).entries().size());assertTrue(f.history.paused());}}
 @Test public void canonicalOwnerReopenDoesNotPersistPauseButDoesPersistMaintain()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.setMaintaining(true,1,f.permit);f.history.setPaused(true);HistoryStore reopened=new HistoryStore(f.catalog,f.permit);assertFalse(reopened.paused());assertTrue(reopened.readCurrent(2,f.permit).maintaining());}}
 @Test public void resumeSyncsEachCurrentPageOnceNotThePausedIntermediateNavigation()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.recordVisit(page(1),1,f.permit);f.history.setPaused(true);f.history.recordVisit(page(2),2,f.permit);HistoryStore.Change change=f.history.setPaused(false);HistoryStore.Snapshot s=f.history.resumeCurrentPages(change,Arrays.asList(page(3),page(4)),10,f.permit);assertEquals(3,s.entries().size());assertEquals(0,s.query("example.test/2",0,100).size());assertEquals(1,s.query("example.test/3",0,100).size());assertThrows(IllegalStateException.class,()->f.history.resumeCurrentPages(change,Collections.singletonList(page(3)),11,f.permit));}}
 @Test public void oldResumeTicketCannotRecordAfterAnotherPauseTransition()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.setPaused(true);HistoryStore.Change old=f.history.setPaused(false);f.history.setPaused(true);f.history.setPaused(false);assertThrows(IllegalStateException.class,()->f.history.resumeCurrentPages(old,Collections.singletonList(page(1)),1,f.permit));assertEquals(0,f.history.readCurrent(2,f.permit).entries().size());}}
 @Test public void resumeRejectsDuplicateNativePagesBeforeAnyWrite()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.setPaused(true);HistoryStore.Change change=f.history.setPaused(false);assertThrows(IllegalArgumentException.class,()->f.history.resumeCurrentPages(change,Arrays.asList(page(1),page(1)),2,f.permit));assertEquals(0,f.history.readCurrent(3,f.permit).entries().size());}}
 @Test public void clearWhileMaintainingIsRejectedByActualIoNotJustDisabledButton()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.recordVisit(page(1),1,f.permit);f.history.setMaintaining(true,2,f.permit);assertThrows(IllegalStateException.class,()->f.history.clearTimed(f.permit));assertEquals(1,f.history.readCurrent(HistoryStore.RETENTION_MS*2,f.permit).entries().size());}}
 @Test public void actualEncryptedReadExpiresAtExactBoundaryAndReopensEmpty()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.recordVisit(page(1),5,f.permit);assertEquals(1,f.history.readCurrent(HistoryStore.RETENTION_MS+4,f.permit).entries().size());assertEquals(0,f.history.readCurrent(HistoryStore.RETENTION_MS+5,f.permit).entries().size());assertEquals(0,new HistoryStore(f.catalog,f.permit).readCurrent(HistoryStore.RETENTION_MS+6,f.permit).entries().size());}}
 @Test public void exactDeleteCannotRetargetAChangedUrlAndExpiryPreventsOpening()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);HistoryStore.Entry e=f.history.recordVisit(page(1),1,f.permit).entries().get(0);assertThrows(IllegalStateException.class,()->f.history.removeExact(e.id(),"https://example.test/other",2,f.permit));assertEquals(1,f.history.readCurrent(2,f.permit).entries().size());assertEquals(0,f.history.removeExact(e.id(),e.url(),3,f.permit).entries().size());}}
 @Test public void ciphertextNeverContainsPrivateTitleOrFullUrl()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.recordVisit(page(1),1,f.permit);String disk=new String(Files.readAllBytes(f.root.resolve(f.ref(OwnedDataCatalog.Family.HISTORY).opaqueRef())),java.nio.charset.StandardCharsets.ISO_8859_1);assertFalse(disk.contains("https://example.test/1"));}}
 @Test public void readDoesNotGuessMissingCatalogIsFreshOrSeedIt()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){assertThrows(IllegalStateException.class,()->f.history.readCurrent(1,f.permit));assertFalse(Files.exists(f.root.resolve(f.ref(OwnedDataCatalog.Family.HISTORY).opaqueRef())));}}
 @Test public void pausedNativeEventCannotReplayWhenIoRunsAfterResume()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.history.setPaused(true);long pausedEvent=f.history.captureVisitRecordingRevision();assertEquals(-1,pausedEvent);HistoryStore.Change resume=f.history.setPaused(false);f.history.resumeCurrentPages(resume,Collections.singletonList(page(3)),10,f.permit);HistoryStore.Snapshot s=f.history.recordVisit(page(2),2,pausedEvent,f.permit);assertEquals(1,s.entries().size());assertEquals(0,s.query("example.test/2",0,100).size());assertEquals(1,s.query("example.test/3",0,100).size());}}
 @Test public void visitQueuedBeforePauseResumeCycleCannotJoinNewRecordingGeneration()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);long old=f.history.captureVisitRecordingRevision();f.history.setPaused(true);f.history.setPaused(false);assertNotEquals(old,f.history.captureVisitRecordingRevision());assertTrue(f.history.recordVisit(page(1),1,old,f.permit).entries().isEmpty());assertEquals(1,f.history.recordVisit(page(2),2,f.history.captureVisitRecordingRevision(),f.permit).entries().size());}}
 @Test public void unchangedRecordingStateDoesNotRejectCurrentQueuedVisit()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);long observed=f.history.captureVisitRecordingRevision();assertFalse(f.history.setPaused(false).changed());assertEquals(1,f.history.recordVisit(page(1),1,observed,f.permit).entries().size());}}
 @Test public void sourceCutoverFencesEvenProcessPauseAndResume()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));assertThrows(SecurityException.class,()->f.history.setPaused(true));assertThrows(SecurityException.class,()->f.history.readCurrent(1,f.permit));}}
 @Test public void actualShelfTransitionAndReopenPreserveExactDeadline()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){seed(f);HistoryStore.Source open=new HistoryStore.Source(id("ws_",1),"副环境",BrowserModels.Level.SECONDARY,true);f.history.recordVisit(new HistoryStore.Page(open,id("tab_",1),"标题","https://example.test/"),1,f.permit);f.history.workspaceChanged(new HistoryStore.Source(id("ws_",1),"副环境",BrowserModels.Level.SECONDARY,false),100,f.permit);HistoryStore reopened=new HistoryStore(f.catalog,f.permit);assertEquals(Long.valueOf(100+HistoryStore.RETENTION_MS),reopened.readCurrent(200,f.permit).entries().get(0).expiresUtcMs());}}
}
